arguments.command:
fname=$(GLOBIGNORE=".:..";
opts=(*);
termy_menu "Select a file to delete" "${opts[@]}") &&
if [ -n "$fname" ] && [ -f "$fname" ]; then
 rm -f "$fname" &&
 printf "\nFile \033[1m%s\033[22m deleted successfully.\n" "$fname" &&
 termy_say -s "File deleted successfully";
else
 printf "\n⛔ Invalid choice or operation cancelled.\n" &&
 termy_say -s "Invalid selection";
fi
